create schema if not exists app_private;
revoke all on schema app_private from public, anon, authenticated;

create table if not exists app_private.sheet_rpc_credentials (
  credential_name text primary key,
  secret_hash bytea not null,
  updated_at timestamptz not null default now()
);
revoke all on app_private.sheet_rpc_credentials from public, anon, authenticated;

-- Preserve the existing spreadsheet RPC secret as a one-way hash before replacing the legacy function body.
do $$
declare
  v_hash bytea;
begin
  select extensions.digest(
           (regexp_match(pg_get_functiondef(p.oid), 'where p_secret = ''([^'']+)'''))[1],
           'sha256'
         )
    into v_hash
  from pg_proc p
  join pg_namespace n on n.oid = p.pronamespace
  where n.nspname = 'public'
    and p.proname = 'sheet_mapping_page'
  limit 1;

  if v_hash is null then
    raise exception 'Could not preserve the existing sheet RPC credential';
  end if;

  insert into app_private.sheet_rpc_credentials(credential_name, secret_hash, updated_at)
  values ('sheet_mapping', v_hash, now())
  on conflict (credential_name) do update
    set secret_hash = excluded.secret_hash,
        updated_at = excluded.updated_at;
end
$$;

create table if not exists review.sheet_manual_mappings (
  manual_mapping_id bigint generated by default as identity primary key,
  source_channel text not null check (source_channel in ('smartstore','makeshop','ably')),
  sellpia_sku text not null,
  channel_code text not null,
  channel_product_name text,
  channel_option_name text,
  match_tier text not null default 'MANUAL_LINKED',
  match_score numeric not null default 100,
  source_spreadsheet_id text,
  source_sheet_name text,
  source_row_no integer,
  confirmed_by text not null default 'google_sheets',
  raw_data jsonb not null default '{}'::jsonb,
  confirmed_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint sheet_manual_mappings_unique unique (source_channel, sellpia_sku, channel_code)
);

alter table review.sheet_manual_mappings enable row level security;
revoke all on review.sheet_manual_mappings from public, anon, authenticated;
revoke all on sequence review.sheet_manual_mappings_manual_mapping_id_seq from public, anon, authenticated;

create or replace function public.sheet_mapping_page(
  p_secret text,
  p_offset integer default 0,
  p_limit integer default 2000
)
returns table(
  import_id bigint,
  source_channel text,
  sellpia_sku text,
  channel_code text,
  channel_product_name text,
  channel_option_name text,
  match_tier text,
  match_score numeric
)
language plpgsql
security definer
set search_path to 'pg_catalog', 'public', 'review', 'app_private', 'extensions'
as $$
begin
  if not exists (
    select 1
    from app_private.sheet_rpc_credentials c
    where c.credential_name = 'sheet_mapping'
      and c.secret_hash = extensions.digest(coalesce(p_secret, ''), 'sha256')
  ) then
    return;
  end if;

  return query
  select q.import_id, q.source_channel, q.sellpia_sku, q.channel_code,
         q.channel_product_name, q.channel_option_name, q.match_tier, q.match_score
  from (
    select
      f.import_id,
      f.source_channel,
      f.sellpia_sku,
      f.channel_code,
      f.channel_product_name,
      f.channel_option_name,
      f.match_tier,
      f.match_score
    from review.final_excel_mapping_import f
    where not exists (
      select 1
      from review.sheet_manual_mappings m
      where m.source_channel = f.source_channel
        and m.sellpia_sku = f.sellpia_sku
        and m.channel_code = f.channel_code
    )

    union all

    select
      1000000000000::bigint + m.manual_mapping_id,
      m.source_channel,
      m.sellpia_sku,
      m.channel_code,
      m.channel_product_name,
      m.channel_option_name,
      m.match_tier,
      m.match_score
    from review.sheet_manual_mappings m
  ) q
  order by q.import_id
  offset greatest(coalesce(p_offset, 0), 0)
  limit least(greatest(coalesce(p_limit, 2000), 1), 2000);
end;
$$;

create or replace function public.sheet_mapping_upsert(
  p_secret text,
  p_items jsonb
)
returns table(saved_count integer)
language plpgsql
security definer
set search_path to 'pg_catalog', 'public', 'review', 'app_private', 'extensions'
as $$
declare
  v_item jsonb;
  v_channel text;
  v_sku text;
  v_product_code text;
  v_option_code text;
  v_channel_code text;
  v_saved integer := 0;
begin
  if not exists (
    select 1
    from app_private.sheet_rpc_credentials c
    where c.credential_name = 'sheet_mapping'
      and c.secret_hash = extensions.digest(coalesce(p_secret, ''), 'sha256')
  ) then
    raise exception 'Invalid sheet credential';
  end if;

  if jsonb_typeof(p_items) <> 'array' then
    raise exception 'p_items must be a JSON array';
  end if;
  if jsonb_array_length(p_items) < 1 or jsonb_array_length(p_items) > 500 then
    raise exception 'p_items must contain between 1 and 500 mappings';
  end if;

  for v_item in select value from jsonb_array_elements(p_items)
  loop
    v_channel := lower(btrim(coalesce(v_item->>'source_channel', '')));
    v_sku := btrim(coalesce(v_item->>'sellpia_sku', ''));
    v_product_code := btrim(coalesce(v_item->>'channel_product_code', ''));
    v_option_code := btrim(coalesce(v_item->>'channel_option_code', ''));

    if v_channel not in ('smartstore','makeshop','ably') then
      raise exception 'Unsupported source_channel: %', v_channel;
    end if;
    if v_sku = '' then
      raise exception 'sellpia_sku is required';
    end if;
    if v_product_code = '' then
      raise exception 'channel_product_code is required';
    end if;

    v_channel_code := case
      when v_option_code = '' then v_product_code
      else v_product_code || '-' || v_option_code
    end;

    insert into review.sheet_manual_mappings(
      source_channel, sellpia_sku, channel_code,
      channel_product_name, channel_option_name,
      match_tier, match_score,
      source_spreadsheet_id, source_sheet_name, source_row_no,
      confirmed_by, raw_data, confirmed_at, updated_at
    ) values (
      v_channel,
      v_sku,
      v_channel_code,
      nullif(btrim(coalesce(v_item->>'channel_product_name', '')), ''),
      nullif(btrim(coalesce(v_item->>'channel_option_name', '')), ''),
      'MANUAL_LINKED',
      100,
      nullif(btrim(coalesce(v_item->>'source_spreadsheet_id', '')), ''),
      nullif(btrim(coalesce(v_item->>'source_sheet_name', '')), ''),
      nullif(v_item->>'source_row_no', '')::integer,
      coalesce(nullif(btrim(v_item->>'confirmed_by'), ''), 'google_sheets'),
      jsonb_build_object(
        'channel_product_code', v_product_code,
        'channel_option_code', v_option_code,
        'matrix_row', nullif(v_item->>'source_row_no', '')::integer
      ),
      now(),
      now()
    )
    on conflict (source_channel, sellpia_sku, channel_code)
    do update set
      channel_product_name = excluded.channel_product_name,
      channel_option_name = excluded.channel_option_name,
      match_tier = 'MANUAL_LINKED',
      match_score = 100,
      source_spreadsheet_id = excluded.source_spreadsheet_id,
      source_sheet_name = excluded.source_sheet_name,
      source_row_no = excluded.source_row_no,
      confirmed_by = excluded.confirmed_by,
      raw_data = excluded.raw_data,
      confirmed_at = now(),
      updated_at = now();

    v_saved := v_saved + 1;
  end loop;

  return query select v_saved;
end;
$$;

revoke all on function public.sheet_mapping_upsert(text, jsonb) from public;
revoke all on function public.sheet_mapping_upsert(text, jsonb) from authenticated;
grant execute on function public.sheet_mapping_upsert(text, jsonb) to anon;
